  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(expected->>'signature') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=expected->>'body_sha256' AND p.provolatile::text=expected->>'volatility' AND NOT p.prosecdef AND NOT p.proretset AND NOT p.proleakproof AND p.prokind='f' AND p.pronargdefaults=0 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND ((p.proname='draft_application_fingerprint' AND p.proisstrict AND l.lanname='sql' AND p.prorettype='text'::regtype) OR(p.proname='protect_draft_revision_source' AND NOT p.proisstrict AND l.lanname='plpgsql' AND p.prorettype='trigger'::regtype))) THEN RAISE EXCEPTION 'DRAFT_REVISION_PREVIOUS_HELPER' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='qf' AND c.relname IN ('product_draft','draft_revision','draft_application') AND (NOT k.convalidated OR NOT k.conenforced OR (k.contype='f' AND (SELECT count(*)<>4 OR NOT bool_and(t.tgisinternal AND t.tgenabled='O') FROM pg_trigger t WHERE t.tgconstraint=k.oid)))) OR (SELECT count(*) FROM pg_trigger WHERE tgrelid IN ('qf.product_draft'::regclass,'qf.draft_revision'::regclass,'qf.draft_application'::regclass) AND NOT tgisinternal)<>1 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='qf.draft_revision'::regclass AND tgname='draft_revision_source' AND tgfoid='qf.protect_draft_revision_source()'::regprocedure AND tgenabled='O' AND tgtype=7 AND tgqual IS NULL AND tgattr=''::int2vector AND tgnargs=0 AND octet_length(tgargs)=0 AND tgconstraint=0 AND NOT tgdeferrable AND NOT tginitdeferred) THEN RAISE EXCEPTION 'DRAFT_REVISION_PREVIOUS_ENFORCEMENT' USING ERRCODE='55000'; END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements('[{"signature":"qf.import_attempts_valid(jsonb,integer,uuid,bigint)","body_sha256":"e8fe07a3c840b7f7c2164c34e3b485e9948e3bfc4c6b2e06dfe31494f094e4c1","language":"plpgsql","volatility":"i","strict":false,"result":"boolean"},{"signature":"qf.protect_validation()","body_sha256":"b0943587540e4737ce009e959b0220523d3a9e34f7c19d14e2dd5bc29b525134","language":"plpgsql","volatility":"v","strict":false,"result":"trigger"},{"signature":"qf.protect_validation_file_stop_ack()","body_sha256":"eba5eca3e2ee26fb977da084b75ffdfc681b13d9a1f36fe8cbe45c27f12d4950","language":"plpgsql","volatility":"v","strict":false,"result":"trigger"},{"signature":"qf.sha256_utf8(text)","body_sha256":"a7668c5ec5661ce809cf17b0d9c7ceee93b8da13ea8408fe0ebf5c71ad030a91","language":"sql","volatility":"i","strict":true,"result":"text"},{"signature":"qf.validation_attempts_valid(text,integer,uuid,bigint)","body_sha256":"2a0bf4bcdda05964e145ce6c3a178a549bb6672534b04dc5a816c33b6ae7c2c7","language":"plpgsql","volatility":"i","strict":false,"result":"boolean"},{"signature":"qf.validation_file_stop_controls_valid(text,uuid,text,text)","body_sha256":"4eb18d73345269ddb12d437089173272a8af11e07f1e04741d92b2148831b7fa","language":"plpgsql","volatility":"i","strict":false,"result":"boolean"},{"signature":"qf.validation_file_stop_proof_valid(jsonb,uuid,jsonb)","body_sha256":"7a19b33d5aa36d1baccb4b6c6e62001043856a623dd03dd9c716e2d9a2d12f94","language":"plpgsql","volatility":"i","strict":false,"result":"boolean"},{"signature":"qf.validation_file_stop_protocol()","body_sha256":"6c93e6e80abd2e60faf5e4f6247150e9ede92973be16f0d5ff43b748119f14c9","language":"sql","volatility":"i","strict":false,"result":"text"},{"signature":"qf.validation_shape_valid(qf.quizpack_validation)","body_sha256":"e09bd590fef549d6566b738832402e3058d1bbe9af184607bcb52adc980d38a6","language":"plpgsql","volatility":"s","strict":false,"result":"boolean"}]'::jsonb) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(expected->>'signature') AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=expected->>'body_sha256' AND l.lanname=expected->>'language' AND p.provolatile::text=expected->>'volatility' AND to_jsonb(p.proisstrict)=expected->'strict' AND p.prorettype::regtype::text=expected->>'result' AND NOT p.prosecdef AND NOT p.proretset AND NOT p.proleakproof AND p.prokind='f' AND p.pronargdefaults=0 AND p.proconfig=ARRAY['search_path=pg_catalog']) THEN RAISE EXCEPTION 'DRAFT_REVISION_PREVIOUS_IO_HELPER' USING ERRCODE='55000'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM qf.quizpack_import i WHERE i.status='receiving' OR i.storage_condition IS DISTINCT FROM 'clean' OR i.reserved_bytes IS DISTINCT FROM 0::bigint OR i.lease_until IS NOT NULL OR qf.import_attempts_valid(i.attempts,i.fence,i.current_attempt_id,i.reserved_bytes) IS NOT TRUE OR EXISTS(SELECT 1 FROM jsonb_array_elements(i.attempts) a WHERE a->>'disposition' IS DISTINCT FROM 'released')) OR EXISTS(SELECT 1 FROM qf.quizpack_validation v WHERE v.status IN ('validating','archiving') OR v.storage_condition IS DISTINCT FROM 'clean' OR v.reserved_bytes IS DISTINCT FROM 0::bigint OR v.lease_until IS NOT NULL OR qf.validation_shape_valid(v) IS NOT TRUE OR qf.validation_attempts_valid(v.attempts_text,v.fence,v.current_attempt_id,v.reserved_bytes) IS NOT TRUE OR qf.validation_file_stop_controls_valid(v.archive_policy_version,v.id,v.attempts_text,v.evidence_metadata_text) IS NOT TRUE OR EXISTS(SELECT 1 FROM jsonb_array_elements(v.attempts_text::jsonb) a WHERE a->>'disposition' IS DISTINCT FROM 'released' OR (a->>'mediaStop' IN ('confirmed','not-started')) IS NOT TRUE)) THEN RAISE EXCEPTION 'DRAFT_REVISION_UNSETTLED_IO' USING ERRCODE='55000'; END IF;
