ALTER TABLE qf.product_draft ADD COLUMN initial_revision integer NOT NULL DEFAULT 1 CHECK(initial_revision=1);
ALTER TABLE qf.product_draft DROP CONSTRAINT product_draft_initial_application_fk;
ALTER TABLE qf.product_draft ADD CONSTRAINT product_draft_initial_application_fk FOREIGN KEY(product_id,id,initial_revision,initial_application_id) REFERENCES qf.draft_application(product_id,draft_id,revision,id) ON DELETE NO ACTION ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE qf.product_draft DROP CONSTRAINT product_draft_current_revision_check;
ALTER TABLE qf.product_draft ADD CONSTRAINT product_draft_current_revision_check CHECK(current_revision BETWEEN 1 AND 100);
ALTER TABLE qf.draft_revision DROP CONSTRAINT draft_revision_revision_check;
ALTER TABLE qf.draft_revision ADD CONSTRAINT draft_revision_revision_check CHECK(revision BETWEEN 1 AND 100);
ALTER TABLE qf.draft_revision ADD CONSTRAINT draft_revision_manifest_once UNIQUE(product_id,canonical_manifest_sha256);
ALTER TABLE qf.draft_revision ADD CONSTRAINT draft_revision_exact_base UNIQUE(product_id,draft_id,revision,canonical_content_sha256,asset_set_sha256);
ALTER TABLE qf.draft_application ADD COLUMN expected_draft_revision integer;
ALTER TABLE qf.draft_application ADD COLUMN expected_base_content_sha256 char(64);
ALTER TABLE qf.draft_application ADD COLUMN expected_base_asset_set_sha256 char(64);
ALTER TABLE qf.draft_application DROP CONSTRAINT draft_application_target_kind_check;
ALTER TABLE qf.draft_application DROP CONSTRAINT draft_application_revision_check;
ALTER TABLE qf.draft_application ADD CONSTRAINT draft_application_revision_check CHECK(revision BETWEEN 1 AND 100);
ALTER TABLE qf.draft_application ADD CONSTRAINT draft_application_operation CHECK(((target_kind='new-draft' AND revision=1 AND expected_draft_revision IS NULL AND expected_base_content_sha256 IS NULL AND expected_base_asset_set_sha256 IS NULL) OR(target_kind='append-revision' AND expected_draft_revision IS NOT NULL AND expected_base_content_sha256 IS NOT NULL AND expected_base_asset_set_sha256 IS NOT NULL AND expected_draft_revision BETWEEN 1 AND 99 AND revision=expected_draft_revision+1 AND expected_base_content_sha256 ~ '^[a-f0-9]{64}$' AND expected_base_asset_set_sha256 ~ '^[a-f0-9]{64}$')) IS TRUE);
ALTER TABLE qf.draft_application ADD CONSTRAINT draft_application_parent_fk FOREIGN KEY(product_id,draft_id,expected_draft_revision,expected_base_content_sha256,expected_base_asset_set_sha256) REFERENCES qf.draft_revision(product_id,draft_id,revision,canonical_content_sha256,asset_set_sha256) ON DELETE NO ACTION ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION qf.draft_revision_application_fingerprint(pid text,iid uuid,vid uuid,rev integer,sha text,did uuid,base integer,ch text,ah text) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
 SELECT qf.sha256_utf8('{"expectedCandidateSha256":'||to_json(sha)::text||',"expectedValidationStateRevision":'||rev::text||',"productId":'||to_json(pid)::text||',"schemaVersion":"quizpack-draft-revision-application.v1","sourceImportId":'||to_json(iid::text)::text||',"sourceValidationId":'||to_json(vid::text)::text||',"target":{"draftId":'||to_json(did::text)::text||',"expectedAssetSetSha256":'||to_json(ah)::text||',"expectedCanonicalContentSha256":'||to_json(ch)::text||',"expectedRevision":'||base::text||',"kind":"append-revision"}}')
$$;
ALTER TABLE qf.draft_application DROP CONSTRAINT draft_application_fingerprint_exact;
ALTER TABLE qf.draft_application ADD CONSTRAINT draft_application_fingerprint_exact CHECK((CASE WHEN target_kind='new-draft' THEN fingerprint=qf.draft_application_fingerprint(product_id,source_import_id,source_validation_id,expected_validation_state_revision,expected_candidate_sha256) WHEN target_kind='append-revision' THEN fingerprint=qf.draft_revision_application_fingerprint(product_id,source_import_id,source_validation_id,expected_validation_state_revision,expected_candidate_sha256,draft_id,expected_draft_revision,expected_base_content_sha256,expected_base_asset_set_sha256) ELSE false END) IS TRUE);

CREATE FUNCTION qf.protect_draft_progress() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE root qf.product_draft; base qf.draft_revision; active boolean;
BEGIN
 SELECT archived_at IS NULL INTO active FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
 IF active IS DISTINCT FROM true THEN RAISE EXCEPTION 'DRAFT_PRODUCT_INACTIVE' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='product_draft' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.current_revision<>1 OR NEW.initial_revision<>1 THEN RAISE EXCEPTION 'DRAFT_INITIAL_REVISION' USING ERRCODE='23514'; END IF;
  ELSIF NEW.current_revision<>OLD.current_revision+1 OR NEW.current_revision>100 OR (to_jsonb(NEW)-'current_revision') IS DISTINCT FROM (to_jsonb(OLD)-'current_revision') THEN RAISE EXCEPTION 'DRAFT_PROGRESS' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT * INTO root FROM qf.product_draft WHERE product_id=NEW.product_id AND id=NEW.draft_id;
  IF root.id IS NULL THEN RAISE EXCEPTION 'DRAFT_ROOT_MISSING' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='draft_revision' THEN
   IF NOT ((NEW.revision=1 AND root.current_revision=1 AND NEW.application_id=root.initial_application_id) OR(NEW.revision>1 AND NEW.revision=root.current_revision+1)) THEN RAISE EXCEPTION 'DRAFT_REVISION_SEQUENCE' USING ERRCODE='23514'; END IF;
  ELSE
   IF NEW.target_kind='new-draft' THEN
    IF NEW.revision<>1 OR root.current_revision<>1 OR NEW.id<>root.initial_application_id THEN RAISE EXCEPTION 'DRAFT_INITIAL_APPLICATION' USING ERRCODE='23514'; END IF;
   ELSIF NEW.target_kind='append-revision' THEN
    SELECT * INTO base FROM qf.draft_revision WHERE product_id=NEW.product_id AND draft_id=NEW.draft_id AND revision=NEW.expected_draft_revision;
    IF (NEW.expected_draft_revision=root.current_revision AND NEW.revision=root.current_revision+1 AND base.canonical_content_sha256=NEW.expected_base_content_sha256 AND base.asset_set_sha256=NEW.expected_base_asset_set_sha256) IS NOT TRUE THEN RAISE EXCEPTION 'DRAFT_BASE_INVALID' USING ERRCODE='23514'; END IF;
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER draft_root_progress BEFORE INSERT OR UPDATE ON qf.product_draft FOR EACH ROW EXECUTE FUNCTION qf.protect_draft_progress();
CREATE TRIGGER draft_revision_progress BEFORE INSERT ON qf.draft_revision FOR EACH ROW EXECUTE FUNCTION qf.protect_draft_progress();
CREATE TRIGGER draft_application_progress BEFORE INSERT ON qf.draft_application FOR EACH ROW EXECUTE FUNCTION qf.protect_draft_progress();

CREATE FUNCTION qf.check_draft_closure() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE pid text; did uuid; root qf.product_draft; n integer; lo integer; hi integer;
BEGIN
 pid:=CASE WHEN TG_OP='DELETE' THEN OLD.product_id ELSE NEW.product_id END;
 IF TG_TABLE_NAME='product_draft' THEN did:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
 ELSE did:=CASE WHEN TG_OP='DELETE' THEN OLD.draft_id ELSE NEW.draft_id END; END IF;
 SELECT * INTO root FROM qf.product_draft WHERE product_id=pid AND id=did;
 IF root.id IS NULL THEN
  IF EXISTS(SELECT 1 FROM qf.draft_revision WHERE product_id=pid AND draft_id=did) OR EXISTS(SELECT 1 FROM qf.draft_application WHERE product_id=pid AND draft_id=did) THEN RAISE EXCEPTION 'DRAFT_CLOSURE_ORPHAN' USING ERRCODE='23514'; END IF;
  RETURN NULL;
 END IF;
 SELECT count(*),min(revision),max(revision) INTO n,lo,hi FROM qf.draft_revision WHERE product_id=pid AND draft_id=did;
 IF (n=root.current_revision AND lo=1 AND hi=root.current_revision AND root.initial_revision=1) IS NOT TRUE OR EXISTS(SELECT 1 FROM qf.draft_revision r LEFT JOIN qf.draft_application a ON a.product_id=r.product_id AND a.draft_id=r.draft_id AND a.revision=r.revision AND a.id=r.application_id WHERE r.product_id=pid AND r.draft_id=did AND (a.id IS NULL OR a.created_by IS DISTINCT FROM r.created_by OR a.created_at IS DISTINCT FROM r.created_at)) THEN RAISE EXCEPTION 'DRAFT_CLOSURE_INVALID' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER draft_root_closure AFTER INSERT OR UPDATE OR DELETE ON qf.product_draft DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION qf.check_draft_closure();
CREATE CONSTRAINT TRIGGER draft_revision_closure AFTER INSERT OR DELETE ON qf.draft_revision DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION qf.check_draft_closure();
CREATE CONSTRAINT TRIGGER draft_application_closure AFTER INSERT OR DELETE ON qf.draft_application DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION qf.check_draft_closure();
REVOKE ALL ON FUNCTION qf.draft_revision_application_fingerprint(text,uuid,uuid,integer,text,uuid,integer,text,text),qf.protect_draft_progress(),qf.check_draft_closure() FROM PUBLIC;

ALTER TABLE qf.audit_event DROP CONSTRAINT audit_target;
ALTER TABLE qf.audit_event ADD CONSTRAINT audit_target CHECK ((((target_kind IS NULL) AND (target_id IS NULL) AND (target_revision IS NULL) AND (action = ANY (ARRAY['bootstrap'::qf.audit_action, 'operator_disabled'::qf.audit_action, 'preauth_created'::qf.audit_action, 'login_succeeded'::qf.audit_action, 'login_failed'::qf.audit_action, 'logout'::qf.audit_action, 'session_revoked'::qf.audit_action]))) OR ((target_kind IS NOT NULL) AND (target_id IS NOT NULL) AND (target_revision IS NOT NULL) AND (target_revision >= 1) AND (actor_id IS NOT NULL) AND (session_id IS NOT NULL) AND (outcome = 'success'::qf.audit_outcome) AND (reason_code IS NULL) AND ((((target_kind)::text = 'product'::text) AND ((target_id)::text ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text) AND (action = ANY (ARRAY['product_created'::qf.audit_action, 'product_updated'::qf.audit_action, 'product_archived'::qf.audit_action, 'product_restored'::qf.audit_action]))) OR (((target_kind)::text = 'category'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['category_created'::qf.audit_action, 'category_updated'::qf.audit_action, 'category_archived'::qf.audit_action, 'category_restored'::qf.audit_action]))) OR (((target_kind)::text = 'tag'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['tag_created'::qf.audit_action, 'tag_updated'::qf.audit_action, 'tag_archived'::qf.audit_action, 'tag_restored'::qf.audit_action]))) OR (((target_kind)::text = 'validation'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['validation_started'::qf.audit_action, 'validation_evidenced'::qf.audit_action, 'validation_rejected'::qf.audit_action, 'validation_interrupted'::qf.audit_action, 'validation_completed'::qf.audit_action, 'validation_recovered'::qf.audit_action, 'validation_retried'::qf.audit_action, 'validation_file_stop_acknowledged'::qf.audit_action]))) OR (((target_kind)::text = 'draft'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (target_revision >= 1 AND target_revision <= 100) AND (action = 'draft_applied'::qf.audit_action)) OR (((target_kind)::text = 'import'::text) AND ((target_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (action = ANY (ARRAY['import_intent_created'::qf.audit_action, 'import_receive_started'::qf.audit_action, 'import_receive_completed'::qf.audit_action, 'import_receive_failed'::qf.audit_action, 'import_receive_recovered'::qf.audit_action])))))));
